// Ensures the generated billing seam files exist before anything tries to
// build.
//
// Each entry is (generated file, checked-in stub, private implementation). The
// generated files are gitignored, and what lands there is decided entirely by
// what the checkout carries:
//
//   - a `_private/` implementation present  -> a re-export pointing at it
//   - nothing but the stub                  -> a copy of the stub
//
// Note "decided entirely": the content is derived from the checkout on every
// run, and a target holding anything else is overwritten. That is the whole
// point of the file. `_private/` is tracked in the internal repository and
// stripped from the public mirror by scripts/publish-github.sh, but the
// one-line re-export that reaches it never was — so every CI checkout used to
// fall through to the stub and ship a build that cheerfully told users it
// could not sell them anything.
//
// The subtler version of that same bug is a working copy: a laptop that ran
// this once without `_private/` kept the stub for ever, because the script
// used to leave any existing target alone. Nothing about a stub looks wrong
// until it is on the App Store telling a paying customer that subscriptions
// are unavailable. Hence `--require-provider`, which release pipelines pass
// and which refuses to let a stub reach an archive at all.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const requireProvider = process.argv.includes("--require-provider");

const seams = [
  {
    target: join(root, "convex", "billing", "provider.ts"),
    stub: join(root, "convex", "billing", "provider.stub.ts"),
    private: join(root, "convex", "billing", "_private", "stripeProvider.ts"),
    reexport: 'export { provider } from "./_private/stripeProvider";\n',
  },
  {
    target: join(
      root,
      "apps",
      "mobile",
      "src",
      "components",
      "billing",
      "index.tsx",
    ),
    stub: join(
      root,
      "apps",
      "mobile",
      "src",
      "components",
      "billing",
      "index.stub.tsx",
    ),
    private: join(
      root,
      "apps",
      "mobile",
      "src",
      "components",
      "billing",
      "_private",
      "payment-ui.tsx",
    ),
    reexport: `export {
  AiAccessRequiredModal,
  BillingSubscriptionPanel,
  CheckoutResultOverlay,
} from "./_private/payment-ui"
`,
  },
];

const BANNER = `// Generated by scripts/ensure-billing-provider.mjs. Gitignored: delete it and
// the next install writes it again. Edit the module it points at, not this.
`;

/** Rewrites only on a real difference, so file watchers are left in peace. */
function writeIfChanged(target, contents) {
  if (existsSync(target) && readFileSync(target, "utf8") === contents) {
    return false;
  }
  writeFileSync(target, contents);
  return true;
}

const stubbed = [];

for (const { target, stub, private: privateImpl, reexport } of seams) {
  const where = relative(root, target);

  if (existsSync(privateImpl)) {
    if (writeIfChanged(target, BANNER + reexport)) {
      console.log(`billing: wired ${where} to the private implementation`);
    }
    continue;
  }

  stubbed.push(where);
  if (requireProvider) continue;

  if (writeIfChanged(target, readFileSync(stub, "utf8"))) {
    console.log(`billing: no provider found, installed the stub (${where})`);
  }
}

if (requireProvider && stubbed.length > 0) {
  console.error(
    [
      "billing: --require-provider was passed and there is no provider to wire.",
      "",
      `Missing an implementation behind: ${stubbed.join(", ")}`,
      "",
      "Building anyway would produce a release that cannot take money and says",
      "so on the paywall. Restore the _private/ sources — this is the internal",
      "repository's tree, not the public mirror's — and run it again.",
    ].join("\n"),
  );
  process.exit(1);
}
